package com.ias.ticket;

import com.ias.trust.Problem;
import jakarta.servlet.http.HttpServletRequest;
import org.h2.tools.RunScript;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import static org.junit.jupiter.api.Assertions.*;

/** Real H2 coordinator transactions. Identity/source facts below are explicit test ports, not production ACKs. */
class FinanceQuoteBoundaryTest {
 ApprovalBoundaryTest fixture;FinanceQuoteBoundary boundary;String operation,quote,group;
 boolean allowed,capable,sourceAvailable;AtomicReference<String> sourceState;
 final MockHttpServletRequest request=new MockHttpServletRequest();
 @BeforeEach void setup()throws Exception{
  fixture=new ApprovalBoundaryTest();fixture.prepare();
  for(String migration:List.of("V11__stock_execution_permits.sql","V12__finance_quote_fencing_candidate.sql","V13__finance_owner_coordination.sql","V22__fee_part_permit.sql"))RunScript.execute(fixture.ddlConnection,new InputStreamReader(Objects.requireNonNull(getClass().getResourceAsStream("/db/migration/"+migration)),StandardCharsets.UTF_8));
  operation=UUID.randomUUID().toString();quote=UUID.randomUUID().toString();group=UUID.nameUUIDFromBytes(("finance:7:9:"+fixture.ticket).getBytes(StandardCharsets.UTF_8)).toString();allowed=true;capable=true;sourceAvailable=true;sourceState=new AtomicReference<>("IN_PROGRESS");
  boundary=new FinanceQuoteBoundary(fixture.tickets,(token,csrf,r)->{assertEquals("test-only",token);assertEquals("csrf",csrf);return Map.of("tenantId","7","userId","88","identityType","EMPLOYEE","enabled",true,"departmentEnabled",true,"permissions",capable?List.of("finance.quote.write"):List.of(),"companyIds",allowed?List.of("9"):List.of());},(binding,state,r)->{
   if(!sourceAvailable)throw new Problem(503,"FINANCE_SOURCE_INTENT_NOT_CONFIGURED");return new FinanceQuoteBoundary.SourceFact(binding,sourceState.get(),"COMMITTED".equals(sourceState.get())?"c".repeat(64):null);
  }){@Override void trusted(HttpServletRequest r){}};
 }
 Map<String,Object> input(){return Map.of("sessionToken","test-only","csrfToken","csrf","ticketId",fixture.ticket,"roundId",fixture.round,"groupId",group,"expectedGroupVersion","0","quoteId",quote,"operationId",operation,"commandDigest","b".repeat(64));}
 Map<String,Object> prepare(){return boundary.prepare(input(),request);}
 Map<String,Object> sourceCommit(){return boundary.sourceCommit(Map.of("tenantId","7","ticketId",fixture.ticket,"operationId",operation,"commandDigest","b".repeat(64),"resultDigest","c".repeat(64)),request);}
 long count(String table){return fixture.db.queryForObject("SELECT COUNT(*) FROM "+table,Long.class);}
 @Test void missingSourceAdapterCannotCreateFenceAndLegacyQuoteRemainsClosed(){sourceAvailable=false;assertEquals(503,assertThrows(Problem.class,this::prepare).status);assertEquals(0,count("ticket_finance_quote_fence"));assertEquals(1,fixture.version());assertEquals(503,assertThrows(Problem.class,()->boundary.quote(input(),request)).status);assertEquals(0,count("ticket_audit"));}
 @Test void freshGroupAndEmptyStockStillOnlyFenceNoGlobalAck(){var result=prepare();assertEquals("FENCING",result.get("coordinationState"));assertEquals("1",result.get("generation"));assertEquals(List.of("approval","stock"),result.get("requiredOwners"));assertEquals(false,result.get("quoteWritable"));assertEquals(false,result.get("executionBarrierClear"));assertEquals("FINANCE_QUOTE_FENCING",assertThrows(Problem.class,()->StockExecutionBoundary.guard(fixture.tickets,fixture.ticket)).code);sourceState.set("COMMITTED");var receipt=sourceCommit();assertEquals("SOURCE_COMMIT_RECORDED",receipt.get("sourceState"));assertEquals(false,receipt.get("globalFreezeAck"));sourceCommit();assertEquals(1,count("ticket_finance_quote_source_result"));assertEquals(2,count("ticket_audit"));assertThrows(Problem.class,()->FinanceQuoteBoundary.guard(fixture.tickets,fixture.ticket));}
 @Test void originalPrepareConcurrentRetriesAreOneImmutableGeneration()throws Exception{try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var gate=new CountDownLatch(1);var futures=new ArrayList<Future<Map<String,Object>>>();for(int i=0;i<6;i++)futures.add(pool.submit(()->{gate.await();return prepare();}));gate.countDown();String freeze=null;for(var future:futures){var result=future.get();if(freeze==null)freeze=result.get("freezeId").toString();assertEquals(freeze,result.get("freezeId"));assertEquals("1",result.get("generation"));}}assertEquals(1,count("ticket_finance_quote_fence"));assertEquals(1,count("ticket_audit"));assertEquals(2,fixture.version());}
 @Test void prepareAuditFaultRollsBackGenerationAndVersionThenOriginalUuidRecovers(){fixture.db.execute("ALTER TABLE ticket_audit ADD CONSTRAINT fail_quote_prepare CHECK(action<>'FINANCE_QUOTE_FENCING')");assertThrows(Exception.class,this::prepare);assertEquals(0,count("ticket_finance_quote_fence"));assertEquals(1,fixture.version());fixture.db.execute("ALTER TABLE ticket_audit DROP CONSTRAINT fail_quote_prepare");assertEquals("1",prepare().get("generation"));assertEquals(1,count("ticket_audit"));}
 @Test void sourceCommitAuditFailureCannotClearFenceOrPartiallyAppend(){prepare();sourceState.set("COMMITTED");long version=fixture.version();fixture.db.execute("ALTER TABLE ticket_audit ADD CONSTRAINT fail_quote_source CHECK(action<>'FINANCE_QUOTE_SOURCE_COMMIT_RECORDED')");assertThrows(Exception.class,this::sourceCommit);assertEquals(0,count("ticket_finance_quote_source_result"));assertEquals(version,fixture.version());assertThrows(Problem.class,()->FinanceQuoteBoundary.guard(fixture.tickets,fixture.ticket));fixture.db.execute("ALTER TABLE ticket_audit DROP CONSTRAINT fail_quote_source");sourceCommit();assertEquals(1,count("ticket_finance_quote_source_result"));assertEquals(version+1,fixture.version());assertThrows(Problem.class,()->FinanceQuoteBoundary.guard(fixture.tickets,fixture.ticket));}
 @Test void abortAndLatePrepareNeverCreateAuthority(){sourceState.set("ABORTED");assertEquals("FINANCE_SOURCE_ABORTED",assertThrows(Problem.class,this::prepare).code);assertEquals(0,count("ticket_finance_quote_fence"));sourceState.set("IN_PROGRESS");prepare();sourceState.set("ABORTED");assertEquals("FINANCE_SOURCE_ABORTED",assertThrows(Problem.class,this::prepare).code);assertEquals(1,count("ticket_finance_quote_fence"));assertThrows(Problem.class,()->FinanceQuoteBoundary.guard(fixture.tickets,fixture.ticket));}
 @Test void currentPermissionAndWholeBindingPrecedeOriginalReplay(){prepare();allowed=false;assertEquals(404,assertThrows(Problem.class,this::prepare).status);allowed=true;capable=false;assertEquals(403,assertThrows(Problem.class,this::prepare).status);capable=true;var changed=new HashMap<>(input());changed.put("commandDigest","d".repeat(64));assertEquals(409,assertThrows(Problem.class,()->boundary.prepare(changed,request)).status);var changedVersion=new HashMap<>(input());changedVersion.put("expectedGroupVersion","1");assertEquals(409,assertThrows(Problem.class,()->boundary.prepare(changedVersion,request)).status);assertEquals(1,count("ticket_finance_quote_fence"));}
 @Test void staleRoundCancellationAndWrongFaultRelationCannotPrepare(){fixture.db.update("UPDATE ticket_record SET current_cancel_request_id=?",UUID.randomUUID().toString());assertEquals("QUOTE_CONTEXT_CHANGED",assertThrows(Problem.class,this::prepare).code);fixture.db.update("UPDATE ticket_record SET current_cancel_request_id=NULL");var changed=new HashMap<>(input());changed.put("roundId",UUID.randomUUID().toString());assertEquals(409,assertThrows(Problem.class,()->boundary.prepare(changed,request)).status);var other=new HashMap<>(input());other.put("groupId",UUID.randomUUID().toString());assertEquals("FAULT_GROUP_RELATION_CHANGED",assertThrows(Problem.class,()->boundary.prepare(other,request)).code);assertEquals(0,count("ticket_finance_quote_fence"));}
 @Test void stockPrepareAndQuoteFenceHaveSingleWinnerOnTicketLock()throws Exception{
  try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var gate=new CountDownLatch(1);var quoteFuture=pool.submit(()->{gate.await();try{prepare();return true;}catch(Problem e){assertEquals("STOCK_EXECUTION_PENDING",e.code);return false;}});var stockFuture=pool.submit(()->{gate.await();try{return fixture.tickets.tx.execute(tx->{fixture.tickets.lockActor(7,77);fixture.db.queryForMap("SELECT id FROM ticket_record WHERE id=? FOR UPDATE",fixture.ticket);StockExecutionBoundary.guard(fixture.tickets,fixture.ticket);fixture.db.update("INSERT INTO ticket_stock_execution VALUES(?,7,77,?,?,?,?,11,'ISSUE',?,UTC_TIMESTAMP(3))",UUID.randomUUID().toString(),fixture.ticket,fixture.round,fixture.assignment,UUID.randomUUID().toString(),"a".repeat(64));return true;});}catch(Problem e){assertEquals("FINANCE_QUOTE_FENCING",e.code);return false;}});gate.countDown();assertNotEquals(quoteFuture.get(),stockFuture.get());}
  assertEquals(1,count("ticket_finance_quote_fence")+count("ticket_stock_execution"));
 }
}
